    const newTask: Task = {
      id: Date.now(),
      title,
      description: '',
      priority: 'High',
      completed: false,
      dueDate,
    };
    dispatch(addTask(newTask));
  }, [dispatch]);

  const handleToggleTask = useCallback((id: number) => {
    dispatch(toggleTask(id));
  }, [dispatch]);

  const handleDeleteTask = useCallback((id: number) => {
    dispatch(deleteTask(id));
  }, [dispatch]);

  const handleUpdateTask = useCallback((updates: Partial<Task> & { id: number }) => {
    dispatch(updateTask(updates));
  }, [dispatch]);

  const handleSortChange = useCallback((val: string) => {
    setSortOption(val);
  }, [setSortOption]);

  const stats = useMemo(() => {
    const total = tasks.length;
    const completed = tasks.filter((t) => t.completed).length;
    const active = tasks.filter((t) => !t.completed).length;
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const overdue = tasks.filter((t) => {
      if (t.completed || !t.dueDate) return false;
      return new Date(t.dueDate) < today;
    }).length;
    return { total, completed, active, overdue };
  }, [tasks]);

  const filteredAndSortedTasks = useMemo(() => {
    let result = tasks.filter((task) => {
      const matchesSearch = task.title.toLowerCase().includes(debouncedSearch.toLowerCase());
      const matchesFilter =
        filter === 'all' ? true :
        filter === 'active' ? !task.completed :
        task.completed;
      return matchesSearch && matchesFilter;
    });

    if (sortOption === 'due-date') {
      result = [...result].sort((a, b) => {
        if (!a.dueDate && !b.dueDate) return 0;
        if (!a.dueDate) return 1;
        if (!b.dueDate) return -1;
        return new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime();
      });
    }
    return result;
  }, [tasks, debouncedSearch, sortOption, filter]);

  const countText = filter === 'all'
    ? `${filteredAndSortedTasks.length} Tasks`
    : `Showing ${filteredAndSortedTasks.length} of ${tasks.length} tasks`;

  return (
    <div className="task-app-container" data-theme={theme}>
      <ThemeToggle />
      {showStatsPanel && (
        <StatsPanel
          total={stats.total}
          completed={stats.completed}
          active={stats.active}
          overdue={stats.overdue}
        />
      )}
      <TaskForm onAdd={handleAddTask} />
      {showFilterBar && (
        <FilterBar
          filter={filter}
          onFilterChange={setFilter}
          sortOption={sortOption}
          onSortChange={handleSortChange}
        />
      )}
      <ErrorBoundary>
        <TaskList
          tasks={filteredAndSortedTasks}
          countText={countText}
          onToggle={handleToggleTask}
          onDelete={handleDeleteTask}
          onUpdate={handleUpdateTask}
          linkToTaskDetail={linkToTaskDetail}
          emptyMessage={filter !== 'all' ? 'No tasks match this filter' : undefined}
        />
      </ErrorBoundary>
    </div>
  );
}

export default TaskApp;

